 public.review_finance_company_purchase_request(uuid,uuid,integer,boolean,jsonb,text) from public,anon,authenticated;
grant execute on function public.save_finance_expense_request(uuid,uuid,integer,text,text,jsonb),public.get_finance_expense_access(),
 public.review_finance_company_purchase_request(uuid,uuid,integer,boolean,jsonb,text) to authenticated;
notify pgrst, 'reload schema';
-- END EMBEDDED MIGRATION 060
-- ONE SELECT-only statement / ONE result row. No business RPC calls.
-- Compare upstream hashes with preflight. Standalone verification cannot establish the prior baseline.
with function_actual as(select proname as name,'public.'||proname||'('||oidvectortypes(proargtypes)||')' as signature,md5(prosrc) as hash,prosecdef as security_definer,provolatile as volatility,proconfig as config,
 has_function_privilege('authenticated',oid,'EXECUTE') authenticated_execute,has_function_privilege('anon',oid,'EXECUTE') anon_execute,
